function makeBucket(capacity, refillPerSec, startMs) {
  let tokens = capacity;
  let last = startMs;
  return function allow(nowMs) {
    const elapsed = (nowMs - last) / 1000;
    tokens = Math.min(capacity, tokens + elapsed * refillPerSec);
    last = nowMs;
    if (tokens >= 1) {
      tokens -= 1;
      return true;
    }
    return false;
  };
}

const allow = makeBucket(3, 1, 0);
allow(0); allow(0); allow(0); // true x3
allow(0);    // false
allow(1000); // true
```
